   850  {
   851      otError      error = OT_ERROR_NONE;
   852      unsigned int command;
   853
   854      SuccessOrExit(error = mDecoder.ReadUintPacked(command));
   855
   856      switch (command)
   857      {
   858      case SPINEL_CMD_NOOP:
   859          error = CommandHandler_NOOP(aHeader);
   860          break;
   861
   862      case SPINEL_CMD_RESET:
   863          error = CommandHandler_RESET(aHeader);
   864          break;
   865
   866      case SPINEL_CMD_PROP_VALUE_GET:
   867      case SPINEL_CMD_PROP_VALUE_SET:
   868      case SPINEL_CMD_PROP_VALUE_INSERT:
   869      case SPINEL_CMD_PROP_VALUE_REMOVE:
   870          error = CommandHandler_PROP_VALUE_update(aHeader, command);
  1190
  1191      sNcpInstance = NULL;
  1192
  1193      return error;
  1194  }
