  1100  otError Commissioner::GeneratePskc(const char *              aPassPhrase,
  1101                                     const char *              aNetworkName,
  1102                                     const Mac::ExtendedPanId &aExtPanId,
  1103                                     Pskc &                    aPskc)
  1104  {
  1105      otError     error      = OT_ERROR_NONE;
  1106      const char *saltPrefix = "Thread";
  1107      uint8_t     salt[OT_PBKDF2_SALT_MAX_LEN];
  1108      uint16_t    saltLen = 0;
  1109
  1110      VerifyOrExit((strlen(aPassPhrase) >= OT_COMMISSIONING_PASSPHRASE_MIN_SIZE) &&
  1111                       (strlen(aPassPhrase) <= OT_COMMISSIONING_PASSPHRASE_MAX_SIZE),
  1112                   error = OT_ERROR_INVALID_ARGS);
  1113
  1114      memset(salt, 0, sizeof(salt));
  1115      memcpy(salt, saltPrefix, strlen(saltPrefix));
  1116      saltLen += static_cast<uint16_t>(strlen(saltPrefix));
  1117
  1118      memcpy(salt + saltLen, aExtPanId.m8, sizeof(aExtPanId));
  1119      saltLen += OT_EXT_PAN_ID_SIZE;
  1120
  1121      memcpy(salt + saltLen, aNetworkName, strlen(aNetworkName));
  1122      saltLen += static_cast<uint16_t>(strlen(aNetworkName));
  1123
  1124      otPbkdf2Cmac(reinterpret_cast<const uint8_t *>(aPassPhrase), static_cast<uint16_t>(strlen(aPassPhrase)),
  1125                   reinterpret_cast<const uint8_t *>(salt), saltLen, 16384, OT_PSKC_MAX_SIZE, aPskc.m8);
  1126
  1127  exit:
  1128      return error;
  1129  }
